<script setup lang="ts">
import { ref, computed, onMounted } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ArrowLeft, UserPlus, Save, Hexagon, CheckCircle2 } from 'lucide-vue-next';
import { useApplication, errorMessage, roleLabel, statusLabel } from '../context';
import { USER_ROLES, USER_STATUSES, type UserRole, type UserStatus } from '../../../domain/constants/user';
const app = useApplication(); const route = useRoute(); const router = useRouter();
const register = !!route.meta.register; const editing = computed(() => typeof route.params.id === 'string');
const id = ref(editing.value ? String(route.params.id) : crypto.randomUUID()); const name = ref(''); const email = ref(''); const password = ref(''); const role = ref<UserRole>('MEMBER'); const status = ref<UserStatus>('PENDING');
const busy = ref(false); const loading = ref(editing.value); const error = ref(''); const success = ref(false); const loaded = ref(!editing.value);
const canEdit = computed(() => !editing.value || app.currentSession()?.role === 'ADMIN');
onMounted(async () => { if (!editing.value) return; try { const user = await app.get({ id: id.value }); name.value = user.name; email.value = user.email; role.value = user.role; status.value = user.status; loaded.value = true; } catch (e) { error.value = errorMessage(e); } finally { loading.value = false; } });
async function submit() {
  busy.value = true; error.value = '';
  try {
    if (editing.value) await app.update({ id: id.value, name: name.value, email: email.value, password: password.value || undefined, role: role.value, status: status.value });
    else await app.create({ id: id.value, name: name.value, email: email.value, password: password.value, role: register ? 'MEMBER' : role.value });
    password.value = ''; success.value = true;
  } catch (e) { error.value = errorMessage(e); } finally { busy.value = false; }
}
</script>
<template>
  <div :class="{ 'register-page': register }"><RouterLink v-if="register" to="/login" class="brand register-brand"><Hexagon :size="30"/> nexo.</RouterLink><div :class="{ 'register-content': register }"><RouterLink :to="register ? '/login' : '/usuarios'" class="back-link"><ArrowLeft :size="17"/>{{ register ? 'Volver al inicio de sesión' : 'Volver a usuarios' }}</RouterLink><div class="page-heading"><div><span class="eyebrow">{{ register ? 'EMPIEZA AQUÍ' : 'GESTIÓN DEL EQUIPO' }}</span><h1>{{ editing ? 'Editar usuario' : register ? 'Crea tu cuenta' : 'Un nuevo integrante' }}<span class="heading-dot">.</span></h1><p class="muted">{{ editing ? 'Mantén la información de tu equipo actualizada.' : 'Los grandes equipos empiezan con una conexión.' }}</p></div></div>
    <div v-if="success" class="panel success-panel" role="status"><CheckCircle2 :size="44"/><h2>{{ editing ? 'Usuario actualizado' : 'Usuario creado correctamente' }}</h2><p v-if="!editing">La cuenta está pendiente de activación. Un administrador debe cambiar su estado a Activo antes de que pueda iniciar sesión.</p><p v-else>Los cambios se guardaron correctamente.</p><button class="button primary" @click="router.push(register ? '/login' : '/usuarios')">{{ register ? 'Ir al inicio de sesión' : 'Ver usuarios' }}</button></div>
    <div v-else class="form-layout"><section class="panel form-panel"><div class="panel-heading"><h2>{{ editing ? 'Información del usuario' : 'Datos del usuario' }}</h2><UserPlus :size="21"/></div><div v-if="error" class="error" role="alert">{{ error }}</div><p v-if="loading" class="empty">Cargando información…</p><form v-else @submit.prevent="submit"><fieldset :disabled="busy || !canEdit || !loaded"><label for="name">Nombre completo</label><input id="name" v-model="name" autocomplete="name" minlength="3" placeholder="Ej. María Rodríguez" required/><label for="user-email">Correo electrónico</label><input id="user-email" v-model="email" type="email" autocomplete="email" placeholder="nombre@organizacion.com" required/><label for="user-password">{{ editing ? 'Nueva contraseña (opcional)' : 'Contraseña' }}</label><input id="user-password" v-model="password" type="password" autocomplete="new-password" minlength="8" :required="!editing" placeholder="Mínimo 8 caracteres"/><small class="field-hint">{{ editing ? 'Déjala vacía para conservar la contraseña actual.' : 'Usa al menos 8 caracteres para proteger tu cuenta.' }}</small><div class="form-row"><div v-if="!register"><label for="role">Rol de acceso</label><select id="role" v-model="role"><option v-for="r in USER_ROLES" :key="r" :value="r">{{ roleLabel[r] }}</option></select></div><div v-if="editing"><label for="status">Estado</label><select id="status" v-model="status"><option v-for="s in USER_STATUSES" :key="s" :value="s">{{ statusLabel[s] }}</option></select></div></div><div v-if="!register" class="identifier"><span>Identificador {{ editing ? '' : '(generado automáticamente)' }}</span><code>{{ id }}</code></div><div class="form-actions"><RouterLink :to="register ? '/login' : '/usuarios'" class="button secondary">Cancelar</RouterLink><button class="button primary" :disabled="busy"><Save :size="17"/>{{ busy ? 'Guardando…' : editing ? 'Guardar cambios' : 'Crear usuario' }}</button></div></fieldset><p v-if="!canEdit" class="notice">Tu rol permite consultar este usuario. Solo un administrador puede modificarlo.</p></form></section><aside class="form-note"><span class="eyebrow">CADA PERSONA CUENTA</span><h2>El acceso adecuado,<br>para cada integrante.</h2><p>Los administradores gestionan el equipo. Los revisores consultan el directorio. Los miembros tienen acceso a su espacio de bienvenida.</p><div class="note-divider"/><p>Las cuentas nuevas quedan pendientes de activación por un administrador.</p></aside></div>
  </div></div>
</template>
